export function lookupNipPosition(nip) {
  if (!nip) return null;
  const cleanNip = String(nip).replace(/[^0-9]/g, "");
  return NIP_POSITION_REFERENCE[cleanNip] || null;
}

export default NIP_POSITION_REFERENCE;
